from PIL import Image, ImageDraw, ImageEnhance
im = Image.open('images/1.jpg').convert('RGB')
def crop_grid(name, box, scale=3, step=30, enh=1.0):
    c = im.crop(box).resize(((box[2]-box[0])*scale,(box[3]-box[1])*scale), Image.LANCZOS)
    if enh != 1.0: c = ImageEnhance.Contrast(c).enhance(enh)
    d = ImageDraw.Draw(c)
    for gx in range(box[0]//step*step, box[2]+1, step):
        if gx < box[0]: continue
        X = (gx-box[0])*scale
        d.line([(X,0),(X,c.size[1])], fill=(0,150,255), width=1)
        if gx % 60 == 0: d.text((X+2,2), str(gx), fill=(255,0,0))
    for gy in range(box[1]//step*step, box[3]+1, step):
        if gy < box[1]: continue
        Y = (gy-box[1])*scale
        d.line([(0,Y),(c.size[0],Y)], fill=(0,150,255), width=1)
        if gy % 60 == 0: d.text((2,Y+2), str(gy), fill=(255,0,0))
    c.save(name)
crop_grid('b_upRm_raw.png', (480, 340, 820, 640), 3, 30, 1.0)
crop_grid('b_lowRapex.png', (850, 860, 1220, 1060), 3, 30, 1.3)
